const visual = {
  prepare: function (input) {
    var reqs = [];
    for (var v = -5; v <= 5; v++) {
      reqs.push({ kind: 'text', payload: String(v) });
    }
    return reqs;
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var axisY = Math.round(H * 0.44);
    var x0 = 64;
    var x1 = W - 64;
    var paths = [];
    var children = [];
    paths.push({ id: 'axis', commands: visualSdk.polyline([[x0, axisY], [x1, axisY]]) });
    children.push({ type: 'path', pathId: 'axis', stroke: '#26354a', strokeWidth: 1.5, fill: 'none' });
    for (var i = 0; i <= 10; i++) {
      var x = x0 + (x1 - x0) * (i / 10);
      x = Math.round(x * 100) / 100;
      paths.push({ id: 'tick' + i, commands: ['M ' + x + ' ' + (axisY - 7), 'L ' + x + ' ' + (axisY + 7)] });
      children.push({ type: 'path', pathId: 'tick' + i, stroke: '#26354a', strokeWidth: 1.5, fill: 'none' });
      var text = String(i - 5);
      var m = metrics && metrics[i] ? metrics[i] : null;
      var tw = m && typeof m.width === 'number' && m.width > 0 ? m.width : (text.length === 2 ? 18 : 9);
      children.push({
        type: 'label',
        x: Math.round((x - tw / 2) * 100) / 100,
        y: axisY + 26,
        text: text,
        fontSize: 15,
        fill: '#26354a'
      });
    }
    return {
      schemaVersion: 1,
      sceneId: 'axis-source',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
